CREATE TABLE IF NOT EXISTS wai_integration_configs (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES wai_organizations(id), user_id uuid NOT NULL REFERENCES wai_users(id), name text NOT NULL, payload bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS wai_connector_mappings (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES wai_organizations(id), user_id uuid NOT NULL REFERENCES wai_users(id), name text NOT NULL, payload bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS wai_memory_preferences (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES wai_organizations(id), user_id uuid NOT NULL REFERENCES wai_users(id), name text NOT NULL, payload bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS wai_memory_examples (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES wai_organizations(id), user_id uuid NOT NULL REFERENCES wai_users(id), name text NOT NULL, payload bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS wai_memory_feedback (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES wai_organizations(id), user_id uuid NOT NULL REFERENCES wai_users(id), name text NOT NULL, payload bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS wai_outbox_delivery (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, result_id uuid NOT NULL, connector_id uuid NOT NULL, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), last_error text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(result_id,connector_id), FOREIGN KEY(tenant_id,result_id) REFERENCES wai_clinical_results(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,connector_id) REFERENCES wai_integration_configs(tenant_id,id));
